<header class="page-header"><div><p class="eyebrow">Prospect</p><h1><?= $prospect?'Edit prospect':'New prospect' ?></h1><p>Choose at least one identity anchor. A selected contact must belong to the selected company.</p></div></header><?php if($errors!==[]):?><div class="validation-summary" role="alert" tabindex="-1" data-validation-summary><h2>Please review</h2><ul><?php foreach($errors as $k=>$m):?><li><?= $escape($m) ?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" action="<?= $escape($actionUrl) ?>"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><?php if($prospect):?><input type="hidden" name="version" value="<?= $escape($prospect['version']) ?>"><?php endif;?><div class="field-grid"><label>Company<select name="company_id"><option value="">No company</option><?php foreach($companies as $c):?><option value="<?= $escape($c['id']) ?>"<?= (string)($values['company_id']??'')===(string)$c['id']?' selected':'' ?>><?= $escape($c['name']) ?></option><?php endforeach;?></select></label><label>Primary contact<select name="primary_contact_id"><option value="">No contact</option><?php foreach($contacts as $c):?><option value="<?= $escape($c['id']) ?>"<?= (string)($values['primary_contact_id']??'')===(string)$c['id']?' selected':'' ?>><?= $escape(trim(($c['first_name']??'').' '.($c['last_name']??''))) ?><?= $c['company_name']?' — '.$escape($c['company_name']):' — Independent' ?></option><?php endforeach;?></select></label><label>Segment<select name="segment" required><?php foreach($segments as $k=>$label):?><option value="<?= $escape($k) ?>"<?= ($values['segment']??'')===$k?' selected':'' ?>><?= $escape($label) ?></option><?php endforeach;?></select></label><label>Source<input name="source" value="<?= $escape($values['source']??'') ?>"></label></div><label>Why them?<textarea name="why_them" rows="4"><?= $escape($values['why_them']??'') ?></textarea></label><label>Business problem<textarea name="business_problem" rows="4"><?= $escape($values['business_problem']??'') ?></textarea></label><label>Qualification notes<textarea name="qualification_notes" rows="4"><?= $escape($values['qualification_notes']??'') ?></textarea></label><fieldset><legend>Qualification understanding</legend><?php foreach(['problem_understood'=>'Problem','timing_understood'=>'Timing','buyer_understood'=>'Buyer','budget_plausible'=>'Plausible budget'] as $k=>$label):?><label class="checkbox-field"><input type="checkbox" name="<?= $escape($k) ?>" value="1"<?= !empty($values[$k])?' checked':'' ?>> <?= $escape($label) ?></label><?php endforeach;?></fieldset><div class="form-actions"><button>Save prospect</button><a href="<?= $escape($cancelUrl) ?>">Cancel</a></div></form>
